  "N032": {
    title: "校园霸凌悲剧",
    content: `
      <div style="font-family: 'Songti SC', 'SimSun', Georgia, serif; line-height: 1.9; color: #2c3e50; max-width: 720px; margin: 0 auto;">
        <div style="border-top: 3px double #1a3a5c; border-bottom: 1px solid #1a3a5c; padding: 12px 0; margin-bottom: 28px; display: flex; justify-content: space-between; align-items: center; font-size: 12px; color: #1a3a5c; letter-spacing: 2px; flex-wrap: wrap; gap: 8px;">
          <span>《江州晚报》· 社会新闻</span>
          <span>2010-11-18 &nbsp;|&nbsp; 第 A04 版</span>
          <span>记者：陈雅</span>
        </div>
        <div style="margin-bottom: 26px;">
          <div style="font-size: 12px; color: #8a6a2c; letter-spacing: 3px; margin-bottom: 10px;">—— 深度调查 ——</div>
          <h2 style="border: none; margin: 0 0 14px 0; padding: 0; font-size: 24px; color: #1a3a5c; font-weight: 700; line-height: 1.5;">
            校园角落的隐秘伤痕：<br>一名小学生长期遭受霸凌后陷入昏迷
          </h2>
          <p style="font-size: 14px; color: #666; margin: 0; line-height: 1.8; font-style: italic;">
            在长达一年多的时间里，五年级学生小林（化名）默默忍受着同学的辱骂、孤立与暴力。直到上周五的下午，他在学校洗手间内遭到三名同学围堵，头部受到重击，至今仍未脱离生命危险。
          </p>
        </div>
        <div style="font-size: 15px; text-align: justify;">
          <p style="text-indent: 2em; margin: 12px 0;">"我早知道这孩子在学校过得不开心，但我不知道是这样……我不敢想他每天都经历了什么。"在江州市第一人民医院的重症监护室外，小林的母亲赵女士掩面痛哭，泣不成声。</p>
          <p style="text-indent: 2em; margin: 12px 0;">监护室内，11岁的小林（化名）安静地躺在病床上，身上插满了管子，靠呼吸机维持生命。医生表示，小林因受到剧烈撞击导致重度颅脑损伤，目前处于深度昏迷状态，何时能醒来仍是未知数。</p>
          <h3 style="color: #1a3a5c; font-size: 17px; border-left: 4px solid #007bff; padding-left: 12px; margin-top: 32px; margin-bottom: 14px;">"从三年级开始，他就被当成了异类"</h3>
          <p style="text-indent: 2em; margin: 12px 0;">悲剧发生在这个月的12号。据校方提供的监控录像显示，当天下午放学后，小林被三名同年级男生强行拉入教学楼一楼的洗手间。三人在洗手间内对小林进行了长达十几分钟的推搡与殴打。在推搡过程中，小林被其中一人用力按向洗手台，额头重重撞在陶瓷边缘，当场倒地不起，流血不止。直到半小时后，才有路过的学生发现并报告老师。</p>
          <p style="text-indent: 2em; margin: 12px 0;">小林的父亲林先生在接受采访时几度哽咽。他告诉我们，这并不是小林第一次受伤。在过去一年多的时间里，小林曾多次带着淤青回家，书包被扔进垃圾桶，课本被撕碎。每次询问，小林都只是低着头说"是自己摔的"。</p>
          <p style="text-indent: 2em; margin: 12px 0;">据小林同班的一名不愿具名的同学透露，小林在学校一直被孤立，甚至被起了难听的绰号。有同学经常抢他的午饭钱，甚至在课间故意将他反锁在教室里。这些持续的霸凌行为，给年幼的小林造成了巨大的心理创伤。据家属反映，小林近半年来开始变得极度内向，在家里几乎不说话，常常把自己关在房间里，甚至出现过用圆规扎自己手臂的自残行为。</p>
          <h3 style="color: #1a3a5c; font-size: 17px; border-left: 4px solid #007bff; padding-left: 12px; margin-top: 32px; margin-bottom: 14px;">"如果早点发现就好了"</h3>
          <p style="text-indent: 2em; margin: 12px 0;">面对记者的询问，学校德育处主任表示，学校对此次事件深表痛心，正在全力配合警方调查，已对涉事的三名学生进行停课处理，并承诺将加强校园安全管理。</p>
          <p style="text-indent: 2em; margin: 12px 0;">目前，当地警方已介入调查。但由于三名施暴者均为未成年人，案件的处理将遵循相关法律规定进行。</p>
          <p style="text-indent: 2em; margin: 12px 0;">在采访结束离开医院时，小林的母亲拉住记者的手，反复说着同一句话："如果早点发现就好了。他太安静了，太安静了，我们以为他只是性格内向……"</p>
          <p style="text-indent: 2em; margin: 12px 0;">这起事件不仅撕开了一个家庭的伤口，也为校园霸凌防治敲响了沉重的警钟。那些在隐秘角落里无声哭泣的孩子，我们还要忽视多久？</p>
        </div>
        <div style="border-top: 1px solid #1a3a5c; border-bottom: 3px double #1a3a5c; padding: 12px 0; margin-top: 36px; text-align: center; font-size: 11px; color: #8a8a8a; letter-spacing: 1px;">
          《江州晚报》社会新闻版 &nbsp;|&nbsp; 江州 · 2010年11月18日
        </div>
      </div>
    `,
    keywords: {}
  },
